refs += [dict(id='regular',title='Regular resolution effectively simulates resolution',authors='Sam Buss; Emre Yolcu',year=2024,url='https://doi.org/10.1016/j.ipl.2024.106489',pdf_url='https://eccc.weizmann.ac.il/report/2024/033/download/',locator='Full author report dated 24 February 2024. Definitions 2.1–2.4 fix general and regular Resolution; Definition 4.3 and Corollary 4.5 concern weak automatability.'),dict(id='hard',title='Automating Resolution is NP-Hard',authors='Albert Atserias; Moritz Müller',year=2019,url='https://arxiv.org/abs/1904.02991',pdf_url='https://www.cs.upc.edu/~atserias/papers/automating-resolution-np-hard/automating-resolution-np-hard.pdf',locator='FOCS 2019; author version dated 3 September 2019, Theorems 1 and 2. Journal version appeared in JACM 67(5), article 31, 2020; author publication list checked.'),dict(id='analysis',title='The Proof Analysis Problem',authors='Noel Arteche; Albert Atserias; Susanna F. de Rezende; Erfan Khaniki',year=2026,url='https://arxiv.org/abs/2506.16956',pdf_url='https://arxiv.org/pdf/2506.16956v2',locator='Full version 2, 19 May 2026, first submitted 20 June 2025; extended abstract at FOCS 2025. Section 1.4 explicitly discusses the still-open weak automatability of Resolution; Section 2.2 defines weak automatability.')]
save(i,dict(title='Weak automatability of Resolution',formal=r'Is there a deterministic algorithm, running in time polynomial in \(|F|+s\), that on input a CNF formula \(F\) and a unary proof budget \(1^{s}\) distinguishes the following two promised cases: \(F\) is satisfiable, or \(F\) has a Resolution refutation with at most \(s\) clauses?',definitions=r'''A CNF formula is an explicit conjunction of clauses over finitely many Boolean variables. Each clause is a disjunction of literals, where a literal is a variable or its negation. Let \(|F|\) be its ordinary binary encoding length, including literal indices and clause boundaries. Variables may be renamed consecutively in polynomial time.

A Resolution derivation is a finite sequence of clauses. Each line is an input clause of \(F\), or follows from two earlier lines by
\[\frac{A\lor x\qquad B\lor\neg x}{A\lor B},\]
where neither \(A\) nor \(B\) contains the pivot variable \(x\). Repeated literals are identified. A refutation ends in the empty clause, which is false under every assignment. Its length is the number of clauses in the sequence. Earlier lines may be reused: this is general directed-acyclic-graph Resolution, with no tree-like or regularity restriction.

The integer \(s\geq1\) is encoded in unary, so the input length is proportional to \(|F|+s\). The short refutation is promised to exist but is not given to the algorithm. Counting total proof symbols instead of clauses changes this polynomial-time question only by polynomial factors, since every clause uses variables of \(F\).

One fixed uniform deterministic algorithm must halt within a fixed polynomial bound on every input. It must output SAT whenever \(F\) is satisfiable, and UNSAT whenever \(F\) has a refutation of length at most \(s\). These cases are disjoint by soundness of Resolution. If \(F\) is unsatisfiable but all its Resolution refutations have length greater than \(s\), either output is allowed. Malformed encodings can be rejected immediately.

No satisfying assignment or refutation has to be output. In particular, the task does not ask whether a refutation of length at most \(s\) exists on every input: an UNSAT output is allowed even when all Resolution refutations are longer. This promise distinction is the decision formulation of weak automatability, corresponding to allowing efficiently checkable proofs in another fixed proof system instead of insisting on Resolution output.''',question_type='yes_no',answer_criterion='Construct the stated deterministic polynomial-time separator, or prove that no such separator exists. A conditional obstruction must state its hypothesis explicitly. Hardness of finding a Resolution refutation, estimating its minimum length, or solving unrestricted SAT does not establish hardness of this particular promise separator without a reduction that respects its two promised cases.',context_blocks=[dict(title='Strong automatability has a known obstruction',text=r'Atserias and Müller show that finding a Resolution refutation in time polynomial in the formula size and the shortest available refutation length would imply \(\mathrm{P}=\mathrm{NP}\). Their proof-length gap distinguishes short refutations from very long or nonexistent ones. The latter side may include unsatisfiable formulas, so it does not give the SAT-versus-short-refutation promise required here.',citation='hard'),dict(title='The distinction survives restrictions on proof shape',text='Buss and Yolcu show that weak automatability of regular Resolution would imply weak automatability of general Resolution. Their definition allows the output proof to use another system. This relation between systems is not an algorithm or a hardness result for the full promise problem.',citation='regular'),dict(title='Recent work retains the weak question',text='The May 2026 full version of The Proof Analysis Problem develops algorithms that analyze supplied proofs of Resolution lower bounds. Section 1.4 still treats weak automatability of Resolution as open. Having such an additional proof as input is a different task from receiving only a formula and a unary budget.',citation='analysis')],why='Asks whether the existence of a short familiar refutation can make unsatisfiability efficiently recognizable even when finding a refutation in that same calculus is hard. This isolates an unresolved limitation of proof search and the theoretical analysis of SAT solvers.',progress=[dict(date='2019-09-03',text='The author version proves NP-hardness of strong Resolution automatability and of distinguishing short from sufficiently long refutations.',citation='hard'),dict(date='2025',text='The STACS invited talk explicitly leaves SAT-versus-short-Resolution-refutation separation open.',citation='primary'),dict(date='2026-05-19',text='The revised full Proof Analysis Problem paper continues to discuss weak automatability as an open question.',citation='analysis')],references=refs,status='open',status_note='Read the complete original abstract, the full regular-Resolution definitions and weak-automatability corollary, the Atserias–Müller author-version main theorems, and the May 2026 full-paper weak-automatability discussion and definitions. Searches through 12 September 2026 found no resolution. The unary-budget promise formulation makes the original distinction precise; no strong-automatability hardness claim has been transferred to it.',model_self_contained=True,requires_context=False,review_note='Recovered the missing weak-automatability question and renamed the card accordingly. Defined the exact Resolution calculus, proof-size convention, unary budget, deterministic resources and behavior outside the promise.',importance=dict(score=c['importance']['score'],method='editorial',reason='A central remaining distinction between proof search in Resolution and recognizing formulas with short refutations, directly relevant to the limits of SAT-solving proof systems. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['The input is a CNF formula and a proof-length budget written in unary.','The algorithm must distinguish satisfiable formulas from those having a short general Resolution refutation.','The proof is not supplied, and the algorithm need not produce a Resolution proof.','Unsatisfiable formulas whose shortest refutations exceed the budget can receive either answer.','Known hardness for finding Resolution proofs does not settle this weaker recognition problem.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','regular','hard','analysis'])),notes=['Recovered the precise weak-automatability target from the untruncated source.','Specified the unary-budget promise, general DAG Resolution and all-input polynomial running time.','Separated the known short-versus-long proof-length hardness from SAT-versus-short-refutation separation.','Checked the still-open discussion in the full May 2026 Proof Analysis Problem revision.'],checked_sources=[r['url'] for r in refs])
